\title{The Sumset Exponent Surface: \\ Asymptotics and Monotonicity of Sharp Sumset Bounds in $\ell_1$ Balls}
\author{Aristotle}
\date{2026-07-14}

\begin{document}
\maketitle

\begin{abstract}
We study the sharp exponent governing sumset lower bounds inside the integer cross-polytope (the $\ell_1$ ball) $B_d(m) = \{x \in \Z^d : |x_1| + \cdots + |x_d| \le m\}$. For $n$ summands and radius $m$, the extremal one-dimensional interval configuration singles out the exponent
\[
p(n,m) = \frac{n\,\log(m+1)}{\log(nm+1)},
\]
which is conjectured to be the sharp exponent in the inequality $|A_1 + \cdots + A_n| \ge (|A_1|\cdots|A_n|)^{1/p}$ in every dimension. Building on the previously established bracket $1 < p(n,m) < n$ and the one-dimensional equality case, we determine the global shape of the two-variable exponent surface $(n,m) \mapsto p(n,m)$. Our main results are: (i) the strict upper bound $p(n,m) < n$ for all $n \ge 2$, $m \ge 1$; (ii) strict monotonicity in the number of summands, $p(n,m) < p(n+1,m)$, which we reduce to and prove via the integer inequality $((n+1)m+1)^n < (nm+1)^{n+1}$; (iii) the radial asymptotics $p(n,m) \to n$ as $m \to \infty$; and (iv) a consequent refutation of radial monotonicity---the map $m \mapsto p(n,m)$ is \emph{not} decreasing, correcting a natural but false conjecture. We give full proof sketches, an algorithmic treatment of the underlying comparisons, and numerical corroboration.
\end{abstract}

\noindent\textbf{Keywords:} sumset, cross-polytope, $\ell_1$ ball, sharp exponent, additive combinatorics, Bernoulli's inequality, geometric-mean bound, radial asymptotics, monotonicity.

\medskip
\noindent\textbf{MSC 2020:} 11B30, 11P70, 52C07, 05A20.

\section{Introduction}

\subsection{Sumsets and their lower bounds}
For finite subsets $A_1, \dots, A_n$ of an abelian group, the \emph{sumset} is
\[
A_1 + \cdots + A_n = \{a_1 + \cdots + a_n : a_j \in A_j\}.
\]
A foundational theme of additive combinatorics is the quantification of the trade-off between the size of a sumset and the additive structure of its summands. The trivial upper bound $|A_1 + \cdots + A_n| \le |A_1|\cdots|A_n|$ is attained only by dissociated configurations, while structured configurations---arithmetic progressions and their higher-dimensional generalizations---minimize the sumset. The corresponding lower bounds are governed by results in the Cauchy--Davenport / Kneser / Pl\"unnecke--Ruzsa family.

We restrict attention to summands confined to a fixed geometric container: the integer cross-polytope of radius $m$,
\[
B_d(m) = \{x \in \Z^d : |x_1| + |x_2| + \cdots + |x_d| \le m\}.
\]
This is the $\ell_1$ ball of radius $m$ intersected with the integer lattice; it is the interval $\{-m,\dots,m\}$ when $d=1$, a lattice diamond when $d=2$, and a lattice octahedron when $d=3$.

\subsection{The sharp exponent}
The natural way to record a sumset lower bound is via a single exponent $p$ in
\begin{equation}\label{eq:star}
|A_1 + \cdots + A_n| \;\ge\; \bigl(|A_1|\cdots|A_n|\bigr)^{1/p}. \tag{$\star$}
\end{equation}
The \emph{sharp} exponent is the smallest $p$ for which \eqref{eq:star} holds for all admissible configurations. Two elementary facts frame the problem.

\begin{itemize}
\item The \emph{geometric-mean bound} always gives a valid exponent $p = n$: $|A_1 + \cdots + A_n| \ge \max_j |A_j| \ge (|A_1|\cdots|A_n|)^{1/n}$, so \eqref{eq:star} holds with $p = n$, and any $q \ge n$ is likewise valid.
\item The \emph{one-dimensional interval} furnishes the extremal configuration. Taking $A_j = \{0, 1, \dots, m\} \subset B_1(m)$, each of size $m+1$, gives $A_1 + \cdots + A_n = \{0, 1, \dots, nm\}$ of size $nm+1$. The borderline exponent in \eqref{eq:star} solves $nm+1 = (m+1)^{n/p}$, that is,
\begin{equation}\label{eq:pdef}
p(n,m) = \frac{n\,\log(m+1)}{\log(nm+1)}.
\end{equation}
\end{itemize}

Earlier work established the bracket $1 < p(n,m) < n$ and the equality case for the interval. The formula \eqref{eq:pdef} is conspicuously independent of the dimension $d$: the radial dilation structure of the cross-polytope is self-similar across dimensions, motivating the central conjecture that \eqref{eq:pdef} is the sharp exponent for \eqref{eq:star} in every dimension. The present paper maps the global shape of the exponent surface $(n,m) \mapsto p(n,m)$.

\subsection{Contributions}
We prove, with complete rigor (throughout, $n \ge 1$ or $n \ge 2$ and $m \ge 1$ as indicated):
\begin{enumerate}
\item \textbf{Strict upper bound} (Theorem~\ref{thm:upper}): $p(n,m) < n$ for $n \ge 2$, $m \ge 1$.
\item \textbf{Strict monotonicity in the number of summands} (Theorem~\ref{thm:monoN}): $p(n,m) < p(n+1,m)$, reduced to the integer power inequality $((n+1)m+1)^n < (nm+1)^{n+1}$ (Lemma~\ref{lem:power}).
\item \textbf{Radial asymptotics} (Theorem~\ref{thm:asymp}): $p(n,m) \to n$ as $m \to \infty$.
\item \textbf{Refutation of radial monotonicity} (Theorem~\ref{thm:nonmono}): $m \mapsto p(n,m)$ is not antitone for $n \ge 2$.
\end{enumerate}

\section{Definitions and preliminaries}

\begin{definition}[Sharp sumset exponent]
For integers $n, m \ge 1$ define
\[
p(n,m) = \frac{n\,\log(m+1)}{\log(nm+1)} \in \R,
\]
where $\log$ denotes the natural logarithm. The denominator $\log(nm+1) > 0$ since $nm + 1 \ge 2$.
\end{definition}

\begin{lemma}[Positivity of the numerator logarithm]\label{lem:pos}
For $m \ge 1$, $\log(m+1) > 0$.
\end{lemma}
\begin{proof}
$m \ge 1$ gives $m + 1 \ge 2 > 1$, and $\log$ is positive on $(1,\infty)$.
\end{proof}

We record the elementary chain used throughout: for $n, m \ge 1$,
\begin{equation}\label{eq:chain}
m + 1 \;\le\; nm + 1 \;\le\; n(m+1),
\end{equation}
the left inequality because $nm \ge m$, the right because $nm + 1 \le nm + n = n(m+1)$. Applying $\log$ to \eqref{eq:chain} yields
\begin{equation}\label{eq:logchain}
\log(m+1) \;\le\; \log(nm+1) \;\le\; \log n + \log(m+1).
\end{equation}

\section{The strict upper bound}

\begin{theorem}[Upper bound]\label{thm:upper}
For all $n \ge 2$ and $m \ge 1$, $\ p(n,m) < n$.
\end{theorem}
\begin{proof}
Since $\log(nm+1) > 0$, the claim $\frac{n\log(m+1)}{\log(nm+1)} < n$ is equivalent, after multiplying by the positive denominator and cancelling $n > 0$, to $\log(m+1) < \log(nm+1)$. This is strict because $m + 1 < nm + 1$ whenever $n \ge 2$ and $m \ge 1$ (then $nm \ge 2m > m$), and $\log$ is strictly increasing.
\end{proof}

\begin{remark}
The exponent $n$ is the geometric-mean exponent, always valid but never sharp inside the diamond: Theorem~\ref{thm:upper} says the cross-polytope's geometry strictly improves on the trivial bound for every radius. With the previously known $p(n,m) > 1$ we obtain the full bracket $1 < p(n,m) < n$.
\end{remark}

\section{Strict monotonicity in the number of summands}

\begin{lemma}[Interval--power comparison]\label{lem:power}
For all $n, m \ge 1$, $\ \bigl((n+1)m + 1\bigr)^n < (nm+1)^{n+1}$.
\end{lemma}
\begin{proof}
Set $A = (n+1)m + 1$ and $B = nm + 1$, so $0 < B < A$. Dividing the target by $A^n > 0$, it suffices to show $B\,(B/A)^n > 1$. Write $B/A = 1 - m/A$ with $0 \le m/A \le 1$. Bernoulli's inequality $(1+x)^n \ge 1 + nx$ (for $x \ge -1$; here $x = -m/A$) gives
\[
\left(\frac{B}{A}\right)^n \ge 1 - \frac{nm}{A} = \frac{A - nm}{A} = \frac{m+1}{A},
\]
since $A = (n+1)m+1 = nm + m + 1$, so $A - nm = m+1$. Hence
\[
B\left(\frac{B}{A}\right)^n \ge \frac{B(m+1)}{A} = \frac{(nm+1)(m+1)}{(n+1)m+1}.
\]
Finally $(nm+1)(m+1) = nm^2 + nm + m + 1 > nm + m + 1 = (n+1)m + 1$, the surplus being exactly the positive term $nm^2$; therefore the ratio exceeds $1$.
\end{proof}

\begin{remark}
The single surplus term $nm^2$ quantifies precisely ``the cost of an extra summand'': it is what makes the inequality, and hence the monotonicity, strict.
\end{remark}

\begin{theorem}[Monotonicity in the number of summands]\label{thm:monoN}
For all $n, m \ge 1$, $\ p(n,m) < p(n+1,m)$.
\end{theorem}
\begin{proof}
All of $\log(nm+1)$, $\log((n+1)m+1)$, $\log(m+1)$ are positive. Cross-multiplying, the claim is equivalent (cancelling the common positive $\log(m+1)$) to
\[
n\,\log\bigl((n+1)m+1\bigr) < (n+1)\,\log(nm+1),
\]
i.e.\ $\log\bigl(((n+1)m+1)^n\bigr) < \log\bigl((nm+1)^{n+1}\bigr)$. By strict monotonicity of $\log$ this is exactly Lemma~\ref{lem:power}.
\end{proof}

\begin{corollary}
For fixed $m$, the sequence $n \mapsto p(n,m)$ is strictly increasing and, by \eqref{eq:logchain}, satisfies $p(n,m) \ge \frac{n\log(m+1)}{\log n + \log(m+1)} \to \infty$ as $n \to \infty$.
\end{corollary}

\section{Radial asymptotics}

\begin{lemma}[Divergence of the numerator]\label{lem:div}
$\log(m+1) \to \infty$ as $m \to \infty$.
\end{lemma}
\begin{proof}
$m \mapsto m+1 \to \infty$ and $\log \to \infty$ at infinity; compose.
\end{proof}

\begin{lemma}[Logarithm-ratio limit]\label{lem:ratio}
For fixed $n \ge 1$, $\ \dfrac{\log(nm+1)}{\log(m+1)} \to 1$ as $m \to \infty$.
\end{lemma}
\begin{proof}
By \eqref{eq:logchain}, for $m \ge 1$,
\[
1 \;\le\; \frac{\log(nm+1)}{\log(m+1)} \;\le\; 1 + \frac{\log n}{\log(m+1)}.
\]
The lower bound is the constant $1$; the upper bound tends to $1$ since $\log n$ is constant while $\log(m+1) \to \infty$ (Lemma~\ref{lem:div}). The squeeze theorem forces the ratio to $1$.
\end{proof}

\begin{theorem}[Radial asymptotics]\label{thm:asymp}
For fixed $n \ge 1$, $\ p(n,m) \to n$ as $m \to \infty$.
\end{theorem}
\begin{proof}
Rewrite $p(n,m) = \dfrac{n}{\log(nm+1)/\log(m+1)}$. By Lemma~\ref{lem:ratio} the denominator tends to $1 \ne 0$, so $p(n,m) \to n/1 = n$.
\end{proof}

\begin{remark}\label{rem:deficit}
The deficit is carried by a bounded correction: from \eqref{eq:logchain},
\[
n - p(n,m) = n\cdot\frac{\log\!\bigl(\tfrac{nm+1}{m+1}\bigr)}{\log(nm+1)}, \qquad \log\!\Bigl(\tfrac{nm+1}{m+1}\Bigr) \in [0, \log n].
\]
Dividing this bounded quantity by the diverging $\log(nm+1)$ yields the vanishing of the deficit, suggesting the finer rate conjecture $(n - p(n,m))\log m \to n\log n$.
\end{remark}

\section{Refutation of radial monotonicity}

\begin{theorem}[Non-monotonicity in the radius]\label{thm:nonmono}
For $n \ge 2$, the map $m \mapsto p(n,m)$ is not antitone.
\end{theorem}
\begin{proof}
Suppose $m \mapsto p(n,m)$ were antitone. By Theorem~\ref{thm:upper}, $p(n,1) < n$. By Theorem~\ref{thm:asymp}, $p(n,m) \to n$, so eventually $p(n,m) > p(n,1)$; pick such $m \ge 1$. Antitonicity would give $p(n,m) \le p(n,1)$, a contradiction.
\end{proof}

\begin{remark}
The refutation is not vacuous: it combines the strict inequality $p(n,1) < n$ with the genuine limit $p(n,m) \to n$. A decreasing sequence bounded above by $p(n,1) < n$ could never approach $n$; the surface must rise toward its asymptote. Thus, on the radial axis, the exponent increases toward the geometric-mean exponent $n$ rather than decreasing.
\end{remark}

\section{Algorithms and computation}
Each result reduces to a finite, verifiable comparison. Evaluating $p(n,m)$ is a constant-time floating-point computation of \eqref{eq:pdef}. Theorem~\ref{thm:monoN} rests on the integer inequality of Lemma~\ref{lem:power}, which can be checked \emph{exactly} on a grid using arbitrary-precision integers. Theorem~\ref{thm:asymp} is corroborated by evaluating $p(n,m)$ along a geometric ladder of radii, observing monotone convergence to $n$ from below (illustrating both the limit and the refutation of Theorem~\ref{thm:nonmono}).

\section{Applications and significance}
The exponent \eqref{eq:pdef} is fundamentally a ratio of log-cardinalities and is thus body-independent: the ratio of the log-size of a symmetric convex lattice body to that of its dilate. This is why the one-dimensional interval predicts the $d$-dimensional diamond and why the phenomenon should extend to arbitrary symmetric convex lattice polytopes. The gap $n - p(n,m) > 0$ measures the loss of independence when $n$ sets share a common container: it grows with the number of summands and shrinks with the radius, vanishing in the large-radius limit. Sharp sumset exponents underlie packing bounds in coding theory, structural results on approximate groups, and lattice-point counting in the geometry of numbers.

\section{Discussion and future work}

\begin{conjecture}[Two-sided monotonicity]
$m \mapsto p(n,m)$ is strictly increasing for every fixed $n \ge 2$, and $n \mapsto p(n,m)$ is strictly increasing for every fixed $m \ge 1$; jointly $p$ is strictly increasing in each argument with limit values $1$ (as $n=1$ or $m \to 0^+$) and asymptote $n$ (as $m \to \infty$).
\end{conjecture}

\begin{conjecture}[Rate of convergence]
For fixed $n \ge 2$, $(n - p(n,m))\log m \to n\log n$ as $m \to \infty$.
\end{conjecture}

\begin{conjecture}[Reciprocal surface]
Writing $1/p(n,m) = \tfrac{1}{n}\,\log(nm+1)/\log(m+1)$, the reciprocal surface $1/p$ is jointly convex on $\{(n,m): n \ge 1, m \ge 1\}$, with level sets asymptotic to the hyperbolae $nm = \mathrm{const}$.
\end{conjecture}

\begin{conjecture}[Dimension-free sharp inequality]
\eqref{eq:star} holds with $p = p(n,m)$ in every dimension $d$; more generally, for any origin-symmetric convex lattice polytope $K$ the sharp exponent equals $n\log|K|/\log|nK|$.
\end{conjecture}

\begin{conjecture}[Rigidity and stability]
Products of intervals uniquely minimize the sumset among configurations of fixed cardinalities, with minimum $(nm+1)^d$; and any configuration within a $(1+\varepsilon)$ factor of the sharp bound is, up to affine transformation, within $O(\varepsilon)$ symmetric-difference density of an arithmetic progression.
\end{conjecture}

\section{Conclusion}
Starting from the compact extremal formula $p(n,m) = n\log(m+1)/\log(nm+1)$, we determined the global qualitative shape of the sumset exponent surface for the integer cross-polytope: strictly below the trivial geometric-mean value $n$, strictly increasing in the number of summands via a clean integer power inequality provable by Bernoulli's inequality, and---contrary to a natural first guess---increasing rather than decreasing in the radius, converging to $n$ in the large-radius limit. These results transform the raw formula into a navigable landscape and lay the groundwork for the deeper dimension-free, rigidity, and stability conjectures that remain open.

