function p_exp(n, m):
    require n >= 1 and m >= 1
    return n * ln(m+1) / ln(n*m + 1)

function squeeze_bounds(n, m):
    lm <- ln(m+1)
    lower <- n*lm / (ln(n) + lm)   if n > 1 else n
    return (lower, n)              # lower <= p(n,m) <= n

function certify_monotonicity_in_n(n_max, m_max):
    failures <- empty list
    for n in 1..n_max:
        for m in 1..m_max:
            lhs <- ((n+1)*m + 1)^n        # exact integer
            rhs <- (n*m + 1)^(n+1)         # exact integer
            if not (lhs < rhs):
                append (n, m) to failures
    return failures                        # empty == certified
